     1	import assert from 'node:assert/strict';
     2	import { test } from 'node:test';
     3	import { fileURLToPath } from 'node:url';
     4	import { handle } from '../src/server.js';
     5	
     6	test('renders the services page inside the layout', async () => {
     7	  const res = await handle('/services?env=production');
     8	  assert.equal(res.status, 200);
     9	  assert.match(res.body, /<title>Services · Harbor<\/title>/);
    10	  assert.match(res.body, /aria-current="page">Services</);
    11	  assert.match(res.body, /<td>notifications<\/td>/);
    12	});
    13	
    14	test('serves every page in the nav', async () => {
    15	  for (const path of ['/', '/services', '/incidents', '/oncall', '/runbooks']) {
    16	    assert.equal((await handle(path)).status, 200, path);
    17	  }
    18	});
    19	
    20	test('answers 503 when the snapshot cannot be read', async () => {
    21	  const dataDir = fileURLToPath(new URL('./no-such-dir/', import.meta.url));
    22	  const res = await handle('/', { dataDir });
    23	  assert.equal(res.status, 503);
    24	  assert.match(res.body, /Snapshot unavailable/);
    25	});
    26	
    27	test('answers 404 for an unknown path', async () => {
    28	  assert.equal((await handle('/nope')).status, 404);
    29	});
    30	
    31	test('serves the stylesheets and the script', async () => {
    32	  for (const name of ['kit.css', 'app.css', 'kit.js']) {
    33	    assert.equal((await handle(`/public/${name}`)).status, 200, name);
    34	  }
    35	});

