=== src/pages/overview.js
     1	import { button } from '#kit/button';
     2	import { escapeHtml } from '../html.js';
     3	
     4	// One panel per environment, counting the services that are not passing
     5	// their health checks.
     6	export function renderOverview(snapshot) {
     7	  const environments = [...new Set(snapshot.services.map((s) => s.environment))].sort();
     8	  const panels = environments.map((env) => {
     9	    const services = snapshot.services.filter((s) => s.environment === env);
    10	    const unhealthy = services.filter((s) => s.health !== 'passing').length;
    11	    const pill =
    12	      unhealthy === 0
    13	        ? '<span class="pill pill-green">all passing</span>'
    14	        : `<span class="pill pill-red">${unhealthy} not passing</span>`;
    15	    const link = button({
    16	      label: 'View services',
    17	      href: `/services?env=${encodeURIComponent(env)}`,
    18	      variant: 'secondary',
    19	      size: 'sm',
    20	    });
    21	    return `<section class="panel">
    22	  <h2>${escapeHtml(env)}</h2>
    23	  <p>${services.length} services</p>
    24	  ${pill}
    25	  <footer>${link}</footer>
    26	</section>`;
    27	  });
    28	  return `<h1>Overview</h1>
    29	<p class="muted">Snapshot ${escapeHtml(snapshot.generatedAt)}</p>
    30	<div class="panels">
    31	${panels.join('\n')}
    32	</div>`;
    33	}
=== src/pages/oncall.js
     1	import { button } from '#kit/button';
     2	import { dialog } from '#kit/dialog';
     3	import { escapeHtml } from '../html.js';
     4	
     5	// Who is on call for each team this week, and how pages escalate.
     6	export function renderOncall(snapshot) {
     7	  const rows = [...snapshot.rotations]
     8	    .sort((a, b) => a.team.localeCompare(b.team))
     9	    .map(
    10	      (r) => `<tr>
    11	  <td>${escapeHtml(r.team)}</td>
    12	  <td>${escapeHtml(r.primary)}</td>
    13	  <td>${escapeHtml(r.secondary)}</td>
    14	  <td>${escapeHtml(r.until)}</td>
    15	</tr>`,
    16	    )
    17	    .join('\n');
    18	
    19	  const policy = dialog({
    20	    id: 'escalation',
    21	    title: 'Escalation policy',
    22	    body: `<ol>${snapshot.escalation.map((step) => `<li>${escapeHtml(step)}</li>`).join('')}</ol>`,
    23	  });
    24	  const policyButton = button({
    25	    label: 'Escalation policy',
    26	    variant: 'secondary',
    27	    size: 'sm',
    28	    attrs: { 'data-dialog-open': 'escalation' },
    29	  });
    30	
    31	  return `<div class="title-row">
    32	  <h1>On-call</h1>
    33	  ${policyButton}
    34	</div>
    35	<table class="oncall">
    36	<thead><tr><th>Team</th><th>Primary</th><th>Secondary</th><th>Until</th></tr></thead>
    37	<tbody>
    38	${rows}
    39	</tbody>
    40	</table>
    41	${policy}`;
    42	}
