     4	// The runbook index. Each panel links to the runbook in the wiki and carries
     5	// an anchor the Incidents page links to.
     6	export function renderRunbooks(snapshot) {
     7	  const panels = [...snapshot.runbooks]
     8	    .sort((a, b) => a.title.localeCompare(b.title))
     9	    .map((rb) => {
    10	      const open = button({ label: 'Open runbook', href: rb.url, variant: 'secondary', size: 'sm' });
    11	      return `<section class="panel" id="${escapeHtml(rb.id)}">
    12	  <h2>${escapeHtml(rb.title)}</h2>
    13	  <p>${escapeHtml(rb.summary)}</p>
    14	  <footer>${open}</footer>
    15	</section>`;
    16	    })
    17	    .join('\n');
    18	  return `<h1>Runbooks</h1>
    19	<div class="panels">
    20	${panels}
    21	</div>`;
    22	}
